"""Canonical entities1300–1399, preserving all original source contours."""
import pathlib,json
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'public/data'
def prepare(ids):
 cs=ids['countries'];d=dict(format='dated-entity-resolution',coverageStart=1300,coverageEnd=1399,referenceDate='2026-10-26',qidKeys={},names={k:c['name'] for k,c in cs.items()},records=[])
 for k,c in cs.items():
  if c.get('qid'):d['qidKeys'].setdefault(c['qid'],k)
 for k in ['YUAN','NORTHERN-YUAN','GORYEO','ILKHANATE','GOLDEN-HORDE','DELHI-KHALJI','DELHI-TUGHLAQ','SERBIA-KINGDOM','SERBIA-EMPIRE','BOSNIA-BANATE','BOSNIA-KINGDOM','CILICIA-KINGDOM','POLAND-MEDIEVAL','POLAND-KINGDOM','MING','JOS','BYZANTINE','TREBIZOND','MUSCOVY','CASTILE','ARAGON','NAVARRE-KINGDOM','MARINID','TIMURID','MAMLUKS','FLORENCE-REPUBLIC','LITHUANIA-DUCHY','SAVOY-COUNTY','NORWAY-KINGDOM']:
  if cs[k].get('qid'):d['qidKeys'][cs[k]['qid']]=k
 def rule(names,key,a=1300,b=1399,label=None,admin='',status='independent',note=''):
  d['records'].append(dict(names=names.split('|'),key=key,label=label or cs[key]['name'],entityCode=key,start=a,end=b,admin=admin,status=status,source='https://github.com/AlejandroPico/Historicmap/blob/main/docs/RESEARCH-1300.md',note=note+' Contorno de síntesis anual; no una frontera diaria acreditada.'))
 for n,k in [('Kingdom of France','FRA'),('Crown of Castile','CASTILE'),('Crown of Aragon','ARAGON'),('Kingdom of Portugal','PRT'),('Kingdom of England','ENGLAND'),('Kingdom of Scotland','SCOTLAND'),('Emirate of Granada','GRANADA-EMIRATE'),('Kingdom of Navarre','NAVARRE-KINGDOM'),('Grand Principality of Moscow','MUSCOVY'),('Grand Duchy of Lithuania','LITHUANIA-DUCHY'),('Marinid Sultanate','MARINID'),('Mamluk Sultanate','MAMLUKS'),('Khalji Dynasty','DELHI-KHALJI'),('Tughlaq Dynasty','DELHI-TUGHLAQ'),('Golden Horde','GOLDEN-HORDE'),('Timurid Empire','TIMURID'),('Armenian Kingdom of Cilicia','CILICIA-KINGDOM'),('Republic of Florence','FLORENCE-REPUBLIC'),('Republic of Venice','HIST-Q4948'),('Republic of Genoa','HIST-Q174306'),('Republic of Ragusa','HIST-Q208169'),('Papal States|Comtat Venaissin','PAPAL-STATES')]:rule(n,k)
 rule('Byzantine Empire','BYZANTINE',note='Las guerras civiles y coemperadores no representan control uniforme ni una sucesión sin interrupciones en Constantinopla.')
 rule('Empire of Trebizond','TREBIZOND',note='Serie soberana separada de Constantinopla; no se le atribuye automáticamente el emperador paleólogo.')
 rule('Yuan Dynasty','YUAN',b=1367,note='El título de gran khan no implica administración unificada de todos los poderes mongoles.')
 rule('Yuan Dynasty','YUAN',a=1368,b=1368,note='Transición de1368 dentro del año; el agregado anual no acredita control continuo deChina hasta el31dediciembre.')
 rule('Yuan Dynasty','YUAN',a=1369,b=1374,status='source-reference',label='Antiguos dominios Yuan · contorno de transición sin resolver',note='El agregado de fuente persiste hasta1374,después de la caída deDadu de1368. No acredita dominio delYuan delNorte sobreChinaMing. La sedeMing abre su ficha separada sin inventar un frente.')
 rule('Northern Yuan','NORTHERN-YUAN',a=1369,note='Poder norteño tras la caída deDadu; no se prolonga automáticamente la soberanía efectiva sobreChina Ming.')
 rule('Northern Yuan','NORTHERN-YUAN',a=1368,b=1368,note='Inicio de la fase norteña durante1368; no todo el territorio del antiguo imperio.')
 rule('Ming Dynasty','MING',a=1368)
 rule('Goryeo','GORYEO',b=1392,note='Reino con instituciones y sucesiones propias; la dependencia deYuan no lo convierte automáticamente en la misma entidad política.')
 rule('Goryeo|Joseon','JOS',a=1393,note='Dinastía Joseon desde1392; la cartografía anual no tiene un día uniforme del cambio.')
 rule('Joseon','JOS',a=1392,b=1392,note='Se corrige elQIDdeGojoseon antiguo de la fuente; transición durante1392, no continuidad prehistórica.')
 rule('Ilkhanate','ILKHANATE',b=1335)
 rule('Ilkhanate','ILKHANATE',a=1336,status='source-reference',label='Dominios ilkaníes · fragmentación y pretendientes',note='Tras1335 hay regímenes rivales y poderes sucesores. Un título no acredita control de todo el contorno heredado.')
 rule('Kingdom of Serbia|Serbian Empire','SERBIA-KINGDOM',b=1345)
 rule('Kingdom of Serbia|Serbian Empire','SERBIA-EMPIRE',a=1346,b=1371,note='Elevación imperial deDušan en1346; no se adelanta a su acceso al trono real de1331.')
 rule('Kingdom of Serbia|Serbian Empire','SERBIA-EMPIRE',a=1372,status='source-reference',label='Poderes serbios · fragmentación posterior a1371',note='La persistencia del agregado no acredita continuidad de un emperador con gobierno uniforme.')
 rule('Banate of Bosnia|Kingdom of Bosnia','BOSNIA-BANATE',b=1376)
 rule('Banate of Bosnia|Kingdom of Bosnia','BOSNIA-KINGDOM',a=1377,note='Coronación deTvrtko durante1377, distinta de su cargo anterior de ban.')
 rule('Kingdom of Poland','POLAND-MEDIEVAL',b=1384,note='La fragmentación territorial,la reunificación y la coronación de1320 son procesos distintos. No se usan automáticamente los títulos bohemios o húngaros de un mismo soberano.')
 rule('Kingdom of Poland','POLAND-KINGDOM',a=1385,note='Fase de unión dinástica posterior aKrewo; no es laMancomunidad de1569.')
 rule('Old Kingdom of Norway','NORWAY-KINGDOM',note='La fuente usa elQIDdeMargaritaI, una persona. Se conserva el reino como entidad política y sus intervalos de soberanos propios.')
 rule('Kingdom of Denmark|Danish Magnates','DNK',note='Realeza,poder aristocrático y períodos sin rey no son un gobierno nacional continuo de un mismo titular.')
 rule('Kingdom of Sweden','SWE',note='Mandatos de la corona sueca separados de los noruegos y daneses; Kalmar no se anticipa a1397.')
 rule('Kamakura Shogunate','JPN',b=1333,label='Japón · shogunato Kamakura y corte imperial',note='Shogun,regentesHōjō y emperador son cargos distintos; no se anticipa el gobierno Ashikaga.')
 rule('Kenmu Restoration','JPN',a=1333,b=1336,label='Japón · Restauración Kenmu',note='La restauración imperial no resuelve por sí sola todos los poderes regionales.')
 rule('Kenmu Restoration','JPN',a=1337,b=1343,label='Japón · Ashikaga y cortes rivales',note='La etiquetaKenmu de fuente persiste hasta1343,después del final de la restauración en1336. Se corrigen identidad y autoridades; no se certifica con ese agregado un límite entre las cortes delNorte ySur.')
 rule('Ashikaga Shogunate','JPN',a=1336,label='Japón · Ashikaga y cortes rivales',note='La formación del régimen y el nombramiento shogunal de1338 son fechas distintas. Cortes delNorte ySur hasta1392; no se inventan sus fronteras.')
 rule('Holy Roman Empire|Holy Roman Empire Minor States','HIST-Q12548',label='Estados agrupados del Sacro Imperio',note='La dignidad imperial no convierte a los miembros en territorio nacional de un único soberano.')
 rule('House of Habsburg','HABSBURG-MONARCHY',status='source-reference',note='Dominios y ramas familiares, no una persona ni un gobierno único de todos los miembros delImperio.')
 for n,k in [('House of Luxembourg','LUXEMBOURG-DOMAINS'),('House of Ascania','ASCANIA-DOMAINS'),('House of Valois-Anjou|House of Anjou-Sicily|Capetian House of Anjou','VALOIS-ANJOU-DOMAINS'),('House of Tocco','TOCCO-DOMAINS'),('House of Wittelsbach','WITTELSBACH-DOMAINS')]:rule(n,k,status='source-reference',note='Agregado dinástico; la familia no equivale a una entidad nacional ni tiene un gobernante único de todas sus ramas.')
 rule('House of Bourbon','BOURBON-DUCHY',note='Dominio ducal de fuente, no monarquía borbónica francesa antes de1589.')
 rule('County of Savoy','SAVOY-COUNTY',note='Condado; no se anticipa la dignidad ducal de1416.')
 rule('County of Urgell','URGELL-COUNTY')
 rule('Electorate of Saxony','SAXONY-ELECTORATE',note='Sajonia-Wittenberg y su dignidad electoral, no un gobierno de todos los dominios sajones.')
 rule('Margraviate of Brandenburg','ELECTORATE-BRANDENBURG',note='Dignidad margravial/electoral, no el reino prusiano posterior.')
 rule('Duchy of Bavaria','BAVARIA-DUCHY',note='Ducados y ramas divididos; no se atribuye todo el contorno a un único duque sin evidencia regional.')
 rule('Tenochtitlan','TENOCHTITLAN',a=1325,note='Ciudad-Estado mexica anterior a laTripleAlianza de1428; no se anticipa el imperio posterior.')
 rule('Tenochtitlan','TENOCHTITLAN',b=1324,status='source-reference',note='La fundación tradicional de1325 tiene variantes. La geometría anterior no acredita por sí sola una ciudad-Estado de límites precisos.')
 rule('Cuzco','CUSCO-KINGDOM',note='Reino deCusco anterior a la expansión imperial tradicional de1438; cronologías tempranas parcialmente legendarias.')
 rule('Later Mayan City-States','HIST-Q28567',status='source-reference',label='Estados mayas · agregado de fuente',note='Civilización y diversas ciudades, no un país de gobernante único.')
 rule('Puebloans - Aztec Regional System','PUEBLO-REGIONAL',status='source-reference',label='Pueblos ancestrales · sistema regional deAztec',note='Referencia arqueológica del suroeste norteamericano, no el imperio mexica ni laTripleAlianza deMéxico.')
 rule('Viking settlements','VIKING-SETTLEMENTS',status='source-reference',label='Asentamientos nórdicos · agregado de fuente',note='Asentamientos y comunidades distintas, no un país de monarca vikingo único.')
 rule('Khmer Empire','KHM',label='Imperio jemer · período angkoriano',note='Gobiernos y regiones requieren series propias; no se deduce un gobernante de una etiqueta contemporánea.')
 rule('Ngô Dynasty','UNRESOLVED-VIET-SOURCE',status='source-reference',note='La dinastíaNgô del sigloX no acredita esta cronología delXIV; se evita importar sus dirigentes por homonimia.')
 return d
if __name__=='__main__':
 d=prepare(json.loads((OUT/'identities.json').read_text(encoding='utf8')));(OUT/'historical-1300-entities.json').write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8',newline='\n');print('Dated rules',len(d['records']))
